49	func TestHealthzReportsOK(t *testing.T) {
50		router, _ := newTestRouter(t)
51		recorder := doRequest(router, http.MethodGet, "/healthz", "")
52		if recorder.Code != http.StatusOK {
53			t.Fatalf("status = %d, want %d", recorder.Code, http.StatusOK)
54		}
55		if got := recorder.Body.String(); got != `{"database":"ok","status":"ok"}` {
56			t.Fatalf("body = %s", got)
57		}
58	}
