60	func TestUnknownRouteUsesPublishedErrorShape(t *testing.T) {
61		router, _ := newTestRouter(t)
62		recorder := doRequest(router, http.MethodGet, "/missing", "")
63		if recorder.Code != http.StatusNotFound {
64			t.Fatalf("status = %d, want %d", recorder.Code, http.StatusNotFound)
65		}
66		var body map[string]map[string]string
67		if err := json.Unmarshal(recorder.Body.Bytes(), &body); err != nil {
68			t.Fatalf("decode: %v", err)
69		}
70		if body["error"]["code"] == "" || body["error"]["message"] == "" {
71			t.Fatalf("body = %s, want error.code and error.message", recorder.Body.String())
72		}
73	}
