102	func TestPostNetPolicyIncrementsOrder(t *testing.T) {
103		router, _ := newTestRouter(t)
104		doRequest(router, http.MethodPost, "/v1/net-policies", validPolicy)
105		second := strings.Replace(validPolicy, `"default-deny"`, `"allow-dns"`, 1)
