358	// assertSafeErrorMessage checks the published error message carries no SQL,
359	// stack trace or file path.
360	func assertSafeErrorMessage(t *testing.T, recorder *httptest.ResponseRecorder) {
361		t.Helper()
362		var body map[string]map[string]string
363		if err := json.Unmarshal(recorder.Body.Bytes(), &body); err != nil {
364			t.Fatalf("decode error body: %v", err)
365		}
366		msg := strings.ToLower(body["error"]["message"])
367		if msg == "" {
368			t.Fatalf("error.message is empty (body %s)", recorder.Body.String())
369		}
370		for _, leak := range []string{"sql", "sqlite", "goroutine", ".go:", "panic", "/", "\\"} {
371			if strings.Contains(msg, leak) {
372				t.Fatalf("error.message leaks %q: %s", leak, body["error"]["message"])
373			}
374		}
375	}
